

import rclpy
from rclpy.node import Node
from trajectory_msgs.msg import JointTrajectory, JointTrajectoryPoint
from builtin_interfaces.msg import Duration
import numpy as np

from omx_ros2.trajectory_generator import TrajectoryGenerator

# Serviço definido em omx_interfaces
from omx_interfaces.srv import GenerateTrajectory


JOINT_NAMES = ['joint1', 'joint2', 'joint3', 'joint4', 'joint5']

# Número de juntas do braço (sem o gripper)
N_JOINTS = 5

# Limites dinâmicos padrão (rad/s e rad/s²)
DEFAULT_VMAX = [0.35] * N_JOINTS   # ~20 °/s
DEFAULT_AMAX = [0.17] * N_JOINTS   # ~10 °/s²


class TrajectoryGeneratorNode(Node):

    def __init__(self):
        super().__init__('trajectory_generator_node')

        # ----------------------------------------------------------------
        # Gerador de trajetórias
        # ----------------------------------------------------------------
        self.generator = TrajectoryGenerator(
            n=N_JOINTS,
            Vn=DEFAULT_VMAX,
            An=DEFAULT_AMAX,
        )

        # ----------------------------------------------------------------
        # 6.5 — Serviço de geração de trajetória
        # ----------------------------------------------------------------
        self.generate_srv = self.create_service(
            GenerateTrajectory,
            'generate_trajectory',
            self.generate_trajectory_callback
        )

        self.get_logger().info('TrajectoryGeneratorNode iniciado.')

    # ====================================================================
    # 6.5 — Callback do serviço
    # ====================================================================

    def generate_trajectory_callback(self, request, response):
        """
        Request:
            trajectory_msgs/JointTrajectoryPoint[] waypoints
            string[] joint_names
            float64 duration

        Response:
            trajectory_msgs/JointTrajectory trajectory
            bool success
            string message
        """
        try:
            waypoints = request.waypoints
            joint_names = request.joint_names
            duration = request.duration

            self.get_logger().info(
                f"Recebido: {len(waypoints)} waypoints, duration={duration}"
            )

            if len(waypoints) == 0:
                response.success = False
                response.message = "Nenhum waypoint recebido"
                return response

            traj_msg = JointTrajectory()
            traj_msg.joint_names = list(joint_names)

            for wp in waypoints:
                point = JointTrajectoryPoint()

                # posições e demais campos
                point.positions = list(wp.positions)
                point.velocities = list(wp.velocities)
                point.accelerations = list(wp.accelerations)
                point.effort = list(wp.effort)

                # IMPORTANTE: copiar Duration corretamente (evita crash silencioso)
                point.time_from_start = Duration(
                    sec=wp.time_from_start.sec,
                    nanosec=wp.time_from_start.nanosec
                )

                traj_msg.points.append(point)

            response.trajectory = traj_msg
            response.success = True
            response.message = f"Trajetória gerada com {len(waypoints)} pontos"

            self.get_logger().info("Trajetória gerada com sucesso")

            return response

        except Exception as e:
            self.get_logger().error(f"Erro na geração de trajetória: {repr(e)}")
            response.success = False
            response.message = str(e)
            return response


def main(args=None):
    rclpy.init(args=args)
    node = TrajectoryGeneratorNode()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()


if __name__ == '__main__':
    main()
